python3 << 'EOF'
import zipfile
import xml.etree.ElementTree as ET

# Extract text from DOCX files
def extract_docx_text(filepath):
    try:
        with zipfile.ZipFile(filepath, 'r') as docx:
            xml_content = docx.read('word/document.xml')
            root = ET.fromstring(xml_content)

            # Define namespace
            ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

            # Extract all text nodes
            texts = []
            for t in root.findall('.//w:t', ns):
                if t.text:
                    texts.append(t.text)
            return ' '.join(texts)
    except Exception as e:
        return f"Error: {e}"

# Extract text from PPTX file
def extract_pptx_text(filepath):
    try:
        with zipfile.ZipFile(filepath, 'r') as pptx:
            slide_files = [name for name in pptx.namelist() if name.startswith('ppt/slides/slide') and name.endswith('.xml')]
            all_text = []

            for slide_file in slide_files:
                try:
                    xml_content = pptx.read(slide_file)
                    root = ET.fromstring(xml_content)

                    # Define namespace
                    ns = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main'}

                    # Extract all text nodes
                    texts = []
                    for t in root.findall('.//a:t', ns):
                        if t.text:
                            texts.append(t.text)
                    all_text.append(' '.join(texts))
                except Exception as e:
                    continue
            return '\n'.join(all_text)
    except Exception as e:
        return f"Error: {e}"

# Extract from DOCX files
print("=== paper_file_1.docx ===")
text1 = extract_docx_text('papers/all/paper_file_1.docx')
print(text1[:500])

print("\n=== paper_file_2.docx ===")
text2 = extract_docx_text('papers/all/paper_file_2.docx')
print(text2[:500])

print("\n=== DAMOP.pptx ===")
text3 = extract_pptx_text('papers/all/DAMOP.pptx')
print(text3[:500])
EOF

